const suit=c=>Math.floor(c/13);
const rank=c=>c%13+2;
const other=c=>[3,2,1,0][c];
const color=(c,t)=>rank(c)===5&&suit(c)===other(t)?t:suit(c);
const points=(c,t)=>color(c,t)!==t?0:rank(c)===5?5:[2,10,11,14].includes(rank(c))?1:0;
function deal(s,ctx){
  const deck=Array.from({length:52},(_,i)=>i);
  for(let i=51;i>0;i--){
    const j=Math.floor(ctx.random()*(i+1));
    [deck[i],deck[j]]=[deck[j],deck[i]];
  }
  s.hands=Array.from({length:4},(_,i)=>deck.slice(i*9,i*9+9));
  s.stock=deck.slice(36);
  Object.assign(s,{seat:(s.dealer+1)%4,phase:0,trump:-1,bid:0,bidder:-1,bids:0,trick:[],captured:[0,0]});
}
function legal(s){
  const hand=s.hands[s.seat];
  if(!s.trick.length)return hand;
  const lead=color(s.trick[0].card,s.trump);
  return hand.some(c=>color(c,s.trump)===lead)?hand.filter(c=>[lead,s.trump].includes(color(c,s.trump))):hand;
}
function fill(s){
  const t=s.trump;
  const reserve=s.hands.flat().filter(c=>color(c,t)!==t);
  for(let i=0;i<4;i++)s.hands[i]=s.hands[i].filter(c=>color(c,t)===t);
  for(let offset=1;offset<4;offset++){
    const h=s.hands[(s.dealer+offset)%4];
    while(h.length<6)h.push(s.stock.length?s.stock.shift():reserve.shift());
  }
  const h=s.hands[s.dealer];
  h.push(...s.stock.filter(c=>color(c,t)===t));
  for(const c of [...s.stock.filter(c=>color(c,t)!==t),...reserve])if(h.length<6)h.push(c);
  s.stock=[];
  const low=t*13;
  const holder=s.hands.findIndex(hand=>hand.includes(low));
  s.captured[holder%2]=1;
}
function finish(state,ctx,team){
  state.winners=ctx.players.flatMap((_,i)=>team<0||i%2===team?[i]:[]);
  const humans=ctx.players.filter(p=>p.kind==="human"&&p.active!==false);
  const winners=humans.filter(p=>state.winners.includes(ctx.players.indexOf(p)));
  const paid=winners.length?winners:humans;
  return {state,turn:null,payouts:Object.fromEntries(paid.map((p,i)=>[p.id,
    Math.floor(ctx.pot/paid.length)+Number(i<ctx.pot%paid.length)]))};
}
const game={
  newMatch(ctx){
    const state={dealer:3,round:0,totals:[0,0],winners:[]};
    deal(state,ctx);
    return {state,turn:[ctx.players[0].id]};
  },
  applyMove(s,id,m,ctx){
    const fail=()=>{throw new InvalidMove("Choose a legal move on your turn.");};
    const i=s.seat;
    if(!m||Object.keys(m).length!==1||s.winners.length||ctx.players[i].id!==id)fail();
    const state={...s,hands:s.hands.map(h=>[...h]),stock:[...s.stock],trick:[...s.trick],
      totals:[...s.totals],captured:[...s.captured]};
    if(s.phase===0){
      if(m.pass===true){if(s.bids===3&&s.bid===0)fail();}
      else{
        if(!Number.isInteger(m.bid)||m.bid<Math.max(7,s.bid+1)||m.bid>14)fail();
        state.bid=m.bid;state.bidder=i;
      }
      state.bids++;
      state.seat=(i+1)%4;
      if(state.bids===4){state.seat=state.bidder;state.phase=1;}
    }else if(s.phase===1){
      if(!Number.isInteger(m.trump)||m.trump<0||m.trump>3)fail();
      state.trump=m.trump;
      fill(state);
      state.phase=2;
    }else{
      if(!legal(s).includes(m.card))fail();
      const remaining=state.hands[i].filter(c=>c!==m.card);
      if(remaining.length>5){
        const buried=remaining.filter(c=>points(c,s.trump)===0).slice(0,remaining.length-5);
        if(remaining.length-buried.length!==5)fail();
        state.hands[i]=remaining.filter(c=>!buried.includes(c));
      }else state.hands[i]=remaining;
      state.trick.push({seat:i,card:m.card});
      state.seat=(i+1)%4;
      if(state.trick.length===4){
        const lead=color(state.trick[0].card,s.trump);
        const strength=c=>rank(c)*2-Number(suit(c)!==s.trump&&color(c,s.trump)===s.trump)+
          (color(c,s.trump)===s.trump?100:color(c,s.trump)===lead?50:0);
        state.seat=state.trick.reduce((a,b)=>strength(b.card)>strength(a.card)?b:a).seat;
        state.captured[state.seat%2]+=state.trick.reduce((sum,p)=>sum+
          (rank(p.card)===2?0:points(p.card,s.trump)),0);
        state.trick=[];
        if(state.hands.every(h=>!h.length)){
          const bidTeam=s.bidder%2, success=state.captured[bidTeam]>=s.bid;
          const overtime=s.totals.every(score=>score>=55);
          state.totals=state.totals.map((score,j)=>score+(j===bidTeam&&!success?-s.bid:state.captured[j]));
          if(overtime&&success)return finish(state,ctx,bidTeam);
          const qualified=state.totals.flatMap((score,j)=>score>=62?[j]:[]);
          if(qualified.length===1)return finish(state,ctx,qualified[0]);
          if(s.round===23)return finish(state,ctx,state.totals[0]===state.totals[1]?-1:state.totals[0]>state.totals[1]?0:1);
          state.round++;
          state.dealer=(state.dealer+1)%4;
          deal(state,ctx);
        }
      }
    }
    return {state,turn:[ctx.players[state.seat].id]};
  },
  viewFor(s,id,ctx){
    const {hands,stock,seed,...visible}=s;
    const i=ctx.players.findIndex(p=>p.id===id);
    return {...visible,hand:hands[i]??[],legal:s.phase===2&&i===s.seat?legal(s):[]};
  },
  computerMove(s){
    const hand=s.hands[s.seat];
    const support=t=>hand.reduce((sum,c)=>sum+(color(c,t)===t?1+points(c,t):0),0);
    if(s.phase===0){
      const bid=Math.max(7,s.bid+1);
      return bid<=14&&(Math.max(...[0,1,2,3].map(support))>=bid||s.bids===3&&!s.bid)?{bid}:{pass:true};
    }
    if(s.phase===1)return {trump:[0,1,2,3].sort((a,b)=>support(b)-support(a))[0]};
    return {card:[...legal(s)].sort((a,b)=>rank(b)-rank(a))[0]};
  },
  randomMove(s,id,ctx){
    if(s.phase<2)return this.computerMove(s);
    const choices=legal(s);
    return {card:choices[Math.floor(ctx.random()*choices.length)]};
  }
};

